INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (13, 1, 'อ่านจับใจความอย่างเป็นขั้นตอน', 'เรียนรู้การอ่านเพื่อหาใจความสำคัญ แยกข้อเท็จจริง ความคิดเห็น และสรุปก่อนตอบคำถาม', '<h2>อ่านก่อนเล่น: จับใจความสำคัญ</h2><p>ก่อนตอบคำถาม ให้อ่านเรื่องหรือประโยคอย่างตั้งใจ แล้วถามตนเองว่า ใคร ทำอะไร ที่ไหน เมื่อไร และเพราะเหตุใด คำตอบเหล่านี้จะช่วยให้เห็นใจความสำคัญของเรื่อง</p><h3>จำให้แม่น</h3><ul><li>ใจความสำคัญคือสิ่งที่ผู้เขียนต้องการบอกมากที่สุด</li><li>ข้อเท็จจริงตรวจสอบได้ เช่น วันที่ จำนวน หรือเหตุการณ์จริง</li><li>ความคิดเห็นเป็นความรู้สึกหรือความเชื่อ เช่น ดี สนุก น่าจะ</li><li>การสรุปควรใช้คำของตนเองและไม่ใส่รายละเอียดเกินจำเป็น</li></ul><p><strong>วิธีเล่นเกม:</strong> อ่านโจทย์ให้ครบก่อนเลือกคำตอบ แล้วมองหาคำสำคัญในโจทย์ เช่น เพราะว่า ดังนั้น ฉันคิดว่า หรือข้อมูลที่ตรวจสอบได้</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (14, 1, 'หลักภาษาไทยก่อนตอบจริงหรือเท็จ', 'ทบทวนชนิดของคำ ประโยค เครื่องหมายวรรคตอน และคำควบกล้ำก่อนเล่นเกมจริงหรือเท็จ', '<h2>อ่านก่อนเล่น: หลักภาษาไทย</h2><p>ภาษาไทยมีส่วนประกอบหลายอย่าง เช่น พยัญชนะ สระ วรรณยุกต์ ชนิดของคำ และรูปประโยค การเข้าใจหน้าที่ของคำช่วยให้อ่านและเขียนได้ถูกต้อง</p><ul><li>คำนามใช้เรียกคน สัตว์ สิ่งของ สถานที่ หรือความคิด</li><li>คำกริยาใช้บอกการกระทำหรือสภาพ</li><li>คำวิเศษณ์ใช้ขยายคำอื่นให้ชัดเจนขึ้น</li><li>ประโยคที่สมบูรณ์ควรมีใจความครบถ้วน</li></ul><p><strong>วิธีเล่นเกม:</strong> อ่านข้อความแล้วพิจารณาว่าถูกต้องตามหลักภาษาหรือไม่ ถ้าโจทย์ใช้คำว่า เสมอ ทุกครั้ง หรือทั้งหมด ต้องตรวจให้รอบคอบเป็นพิเศษ</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (15, 1, 'เติมคำให้ถูกต้องตามบริบท', 'ฝึกใช้บริบทของประโยคเพื่อเติมคำนาม คำกริยา คำวิเศษณ์ และคำสำคัญทางภาษาไทย', '<h2>อ่านก่อนเล่น: เติมคำจากบริบท</h2><p>การเติมคำต้องดูคำที่อยู่หน้าและหลังช่องว่าง หากช่องว่างเป็นผู้ทำกริยา มักต้องเติมคำนาม หากช่องว่างเป็นการกระทำ มักต้องเติมคำกริยา</p><h3>แนวคิดสำคัญ</h3><ul><li>อ่านประโยคทั้งประโยคก่อนตอบ</li><li>ดูว่าคำตอบควรเป็นคน สิ่งของ การกระทำ หรือคำขยาย</li><li>สะกดคำให้ถูกต้อง โดยเฉพาะคำที่มีสระหรือวรรณยุกต์</li></ul><p><strong>วิธีเล่นเกม:</strong> พิมพ์คำตอบให้ตรงกับความหมายและสะกดให้ถูกต้อง</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (16, 1, 'จับคู่คำกับหน้าที่ในประโยค', 'เรียนรู้คำศัพท์หลักภาษาและหน้าที่ของคำเพื่อจับคู่ให้ถูกต้อง', '<h2>อ่านก่อนเล่น: จับคู่หลักภาษา</h2><p>คำแต่ละชนิดมีหน้าที่ต่างกันในประโยค เช่น ประธานเป็นผู้ทำกริยา กริยาเป็นการกระทำ และกรรมเป็นผู้ถูกกระทำ</p><ul><li>มองหาคำหลักด้านซ้ายก่อน</li><li>นึกถึงหน้าที่หรือความหมายของคำนั้น</li><li>เลือกคำอธิบายด้านขวาที่สัมพันธ์กันที่สุด</li></ul><p><strong>วิธีเล่นเกม:</strong> คลิกคำด้านซ้ายแล้วจับคู่กับความหมายหรือหน้าที่ด้านขวา</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (17, 1, 'เรียงประโยคภาษาไทยให้ถูกลำดับ', 'เรียนรู้โครงสร้างประโยคไทยแบบง่ายก่อนฝึกเรียงคำ', '<h2>อ่านก่อนเล่น: เรียงคำเป็นประโยค</h2><p>ประโยคไทยทั่วไปมักเรียงจากผู้กระทำ ไปสู่การกระทำ แล้วตามด้วยสิ่งที่ถูกกระทำหรือส่วนขยาย เช่น นักเรียน อ่าน หนังสือ ในห้องสมุด</p><h3>ลำดับที่ควรสังเกต</h3><ul><li>ประธาน: ใครหรือสิ่งใดเป็นผู้ทำ</li><li>กริยา: ทำอะไร</li><li>กรรมหรือส่วนเติมเต็ม: ทำกับอะไร</li><li>ส่วนขยาย: ที่ไหน เมื่อไร อย่างไร</li></ul><p><strong>วิธีเล่นเกม:</strong> แตะคำจากคลังคำแล้วเรียงลงช่องให้เป็นประโยคที่อ่านรู้เรื่อง</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (18, 1, 'เรียงตัวอักษรภาษาไทยให้เป็นคำ', 'ฝึกมองรูปคำ พยางค์ และการสะกดคำภาษาไทยก่อนเล่นเกมเรียงตัวอักษร', '<h2>อ่านก่อนเล่น: เรียงตัวอักษรเป็นคำ</h2><p>ภาษาไทยมีพยัญชนะ สระ และวรรณยุกต์ที่ต้องวางรวมกันให้ถูกต้อง บางคำอาจแบ่งเป็นตัวอักษรหรือพยางค์ เช่น หนั-ง-สื-อ เมื่อนำมาเรียงถูกจะเป็นคำว่า หนังสือ</p><ul><li>อ่านโจทย์เพื่อเดาว่าเป็นคำเกี่ยวกับเรื่องใด</li><li>มองหาพยางค์ต้นของคำก่อน</li><li>เรียงตัวอักษรหรือพยางค์ให้เป็นคำที่มีความหมาย</li><li>อ่านคำที่เรียงเสร็จอีกครั้งก่อนกดตรวจ</li></ul><p><strong>วิธีเล่นเกม:</strong> แตะบัตรตัวอักษรด้านบนเพื่อวางลงช่องคำตอบด้านล่าง ถ้าวางผิดให้แตะช่องนั้นเพื่อนำออก</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (19, 1, 'Classroom Vocabulary Before the Quiz', 'Study common classroom words before choosing the correct answer.', '<h2>Learn Before Playing: Classroom Words</h2><p>Classroom vocabulary helps students talk about school life. Read each word and meaning before playing.</p><ul><li>A teacher helps students learn.</li><li>A student learns in class.</li><li>A library is a place for reading books.</li><li>A ruler helps draw straight lines.</li><li>An eraser removes pencil marks.</li></ul><p><strong>How to play:</strong> Read the question carefully, look for the keyword, and choose the best answer.</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (20, 1, 'True or False English Practice', 'Review simple English facts, grammar, and vocabulary before deciding true or false.', '<h2>Learn Before Playing: True or False</h2><p>In a true-or-false game, every word matters. Check the subject, verb, plural form, and meaning before answering.</p><ul><li>Use is with one person or thing.</li><li>Use are with plural nouns.</li><li>Many plural nouns end with s, such as books and pencils.</li><li>A sentence should begin with a capital letter.</li></ul><p><strong>How to play:</strong> Choose True if the whole sentence is correct. Choose False if one part is wrong.</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (21, 1, 'Fill in the Blank with Context Clues', 'Practice using sentence clues to complete English sentences.', '<h2>Learn Before Playing: Fill in the Blank</h2><p>When a word is missing, read the whole sentence first. The words around the blank can tell you if you need a noun, verb, place, or object.</p><ul><li>I, you, we, and they often use the base verb: I study.</li><li>He, she, and it often add s: She reads.</li><li>School objects include pencil, book, notebook, ruler, and eraser.</li></ul><p><strong>How to play:</strong> Type the missing word. Check spelling before submitting.</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (22, 1, 'Match English Words with Thai Meanings', 'Build vocabulary by matching English words with Thai meanings.', '<h2>Learn Before Playing: Vocabulary Matching</h2><p>Matching words helps memory because you connect a new English word with a meaning you already know in Thai.</p><ul><li>Read the English word aloud.</li><li>Think of where you see or use that thing.</li><li>Match it with the Thai meaning that fits best.</li></ul><p><strong>How to play:</strong> Click a word on the left, then click its meaning on the right.</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (23, 1, 'Sentence Order in English', 'Learn basic English word order before arranging words into sentences.', '<h2>Learn Before Playing: English Sentence Order</h2><p>Simple English sentences often follow this order: subject + verb + object or place/time. For example, I study English every day.</p><h3>Remember</h3><ul><li>Subject: who or what the sentence is about</li><li>Verb: the action</li><li>Object or place: what, where, or when</li></ul><p><strong>How to play:</strong> Tap the words in the correct order to make a complete sentence.</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
INSERT INTO lesson_content (game_id, lesson_no, title, summary, body, read_time, status, version_no, published_at, updated_at) VALUES (24, 1, 'School Word Search Vocabulary', 'Study school vocabulary before finding words in the word-search grid.', '<h2>Learn Before Playing: Word Search</h2><p>Word search helps spelling and word recognition. Before playing, read each word aloud and notice its letters.</p><ul><li>Words may go across, down, or diagonally.</li><li>Look for the first and last letter of each word.</li><li>Long words are often easier to find because they have a clearer shape.</li></ul><p><strong>How to play:</strong> Drag across the letters in the grid to select each word.</p>', 7, 'published', 1, now(), now()) ON CONFLICT (game_id, lesson_no) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, body=EXCLUDED.body, read_time=EXCLUDED.read_time, status='published', version_no=lesson_content.version_no + 1, published_at=now(), updated_at=now();
WITH q AS (INSERT INTO questions (game_id, question_text, question_type, order_no, point) VALUES (13, 'ข้อใดเป็นใจความสำคัญของข้อความ: ฝนตกหนักตลอดคืน ทำให้น้ำท่วมถนนหลายสาย นักเรียนจึงมาโรงเรียนสาย', 'mcq', 1, 1) RETURNING question_id) INSERT INTO answers (question_id, answer_text, is_correct, seq_order) VALUES ((SELECT question_id FROM q), 'ฝนตกหนักทำให้น้ำท่วมและนักเรียนมาโรงเรียนสาย', true, 1), ((SELECT question_id FROM q), 'นักเรียนทุกคนชอบฝน', false, 2), ((SELECT question_id FROM q), 'ถนนทุกสายในประเทศน้ำท่วม', false, 3), ((SELECT question_id FROM q), 'โรงเรียนปิดตลอดวัน', false, 4);
WITH q AS (INSERT INTO questions (game_id, question_text, question_type, order_no, point) VALUES (13, 'คำว่า เพราะว่า มักบอกความสัมพันธ์แบบใด', 'mcq', 2, 1) RETURNING question_id) INSERT INTO answers (question_id, answer_text, is_correct, seq_order) VALUES ((SELECT question_id FROM q), 'เหตุผล', true, 1), ((SELECT question_id FROM q), 'เวลา', false, 2), ((SELECT question_id FROM q), 'สถานที่', false, 3), ((SELECT question_id FROM q), 'คำถาม', false, 4);
WITH q AS (INSERT INTO questions (game_id, question_text, question_type, order_no, point) VALUES (13, 'ประโยคใดเป็นข้อเท็จจริง', 'mcq', 3, 1) RETURNING question_id) INSERT INTO answers (question_id, answer_text, is_correct, seq_order) VALUES ((SELECT question_id FROM q), 'ดวงอาทิตย์ขึ้นทางทิศตะวันออก', true, 1), ((SELECT question_id FROM q), 'ฉันว่าท้องฟ้าวันนี้สวยที่สุด', false, 2), ((SELECT question_id FROM q), 'อาหารจานนี้อร่อยมาก', false, 3), ((SELECT question_id FROM q), 'สีแดงน่าจะเหมาะที่สุด', false, 4);
